/** Phase 2A of term-based SaaS billing: the hourly sweep that advances
 * subscription_cycles docs (generated by functions/academic_calendar_billing.js's
 * confirmAcademicCalendar, always starting at cycleStatus:'upcoming') through
 * invoicing, payment reminders, grace period, and - if still unpaid past
 * grace - automatic suspension.
 *
 * Mirrors public_functions/subscription_lifecycle.js's onSchedule config
 * shape, timezone, and enqueueTemplatedEmail idempotency pattern exactly,
 * but operates on subscription_cycles (the new per-term model) rather than
 * schools.subscriptionExpiry (the legacy flat-expiry model, which
 * subscription_lifecycle.js continues to own unchanged - a school with no
 * confirmed cycles is untouched by this file).
 *
 * SERVER TIME ONLY: every comparison below uses Date.now() at the moment
 * the sweep runs, never a client-supplied value - cycles are Admin-SDK-only
 * documents so this is not a defense-in-depth measure, just a correctness
 * one (the sweep must be deterministic regardless of caller).
 *
 * ============================================================================
 * STATE MACHINE (see the pure `decideCycleAction` function below for the
 * exact implementation - this comment documents the reasoning):
 *
 *   upcoming -> invoiced
 *     Trigger: now >= termStart - invoiceLeadDays (platform_billing_config/
 *     renewal.invoiceLeadDays, default 14 - same fallback constant as
 *     functions/academic_calendar_billing.js's DEFAULT_INVOICE_LEAD_DAYS,
 *     duplicated rather than cross-imported since functions/ and
 *     public_functions/ are separate Cloud Functions codebases).
 *     Idempotency guard: only fires while cycleStatus is still 'upcoming'.
 *     Side effect: invoiceIssuedAt:serverTimestamp(), paymentStatus:'unpaid',
 *     enqueue cycle_invoice_issued email, eventId
 *     `cycle_invoice_issued_${cycleId}` (fires exactly once ever).
 *
 *   invoiced / paymentPending -> gracePeriod
 *     Trigger: now > paymentDueAt && now <= graceEndsAt, still unpaid.
 *     Idempotency guard: only fires while cycleStatus is 'invoiced' or
 *     'paymentPending' (never re-applied once already 'gracePeriod' or
 *     beyond).
 *     paymentPending judgment call: Phase 1 never writes this status and
 *     nothing else in this codebase writes it either (the enum keeps it as
 *     a reserved future state, e.g. for a payment awaiting manual review
 *     mid-cycle). This sweep treats it as a synonym for 'invoiced' for
 *     every purpose (reminder tiers + this transition) rather than growing a
 *     third code path with no observable behavioral difference - if a
 *     future feature starts writing paymentPending with different meaning,
 *     it should own this decision explicitly instead of inheriting it.
 *
 *   gracePeriod -> overdue
 *     Trigger: now > graceEndsAt, still unpaid.
 *     Idempotency guard: only fires while cycleStatus is 'gracePeriod'.
 *
 *   overdue -> (stays 'overdue'; triggers suspension side-effect, not a
 *   cycle-status transition)
 *     Judgment call (the key ambiguity in the spec): the subscription_cycles
 *     cycleStatus enum lists 'suspended' as a valid value, which reads as if
 *     an overdue-and-unpaid cycle should itself become cycleStatus:
 *     'suspended'. This implementation deliberately does NOT do that -
 *     cycleStatus stays 'overdue' forever (until paid/cancelled/expired),
 *     and suspension is instead reflected on the SCHOOL doc
 *     (schools/{id}.status='suspended', accessMode='blocked'), via the same
 *     suspendSchoolCore transaction portal_domains.js's owner-invoked
 *     setSchoolLifecycleStatus uses. Reasoning:
 *       1. "Suspended" describes what happened to the SCHOOL's access, not a
 *          property of the billing cycle itself - the cycle is still
 *          "overdue" (that's the invoice's true status); it's the school's
 *          access that changed state as a consequence.
 *       2. schools/{id}.status is the single field firestore.rules and the
 *          Flutter client access gate already trust (see portal_domains.js's
 *          ACCESS_MODE_FOR_STATUS comment) - inventing a second,
 *          cycle-scoped "suspended" signal that nothing reads would be dead
 *          state that could drift from the real one.
 *       3. A school can have more than one subscription_cycles doc over its
 *          lifetime (one per term); "cycleStatus:'suspended'" on one
 *          specific overdue cycle doc would not obviously generalize to "is
 *          this school currently suspended" without re-deriving it from the
 *          cycle anyway - so the school doc remains the single source of
 *          truth for access, and 'overdue' remains the cycle's own honest
 *          terminal-ish status until a payment or cancellation resolves it.
 *     This is applied consistently: nowhere in this file is
 *     cycleStatus ever set to 'suspended'.
 *     Idempotency guard for the suspension side-effect: suspendSchoolCore
 *     itself no-ops (no re-write, no re-audit-log, no re-revocation) if
 *     schools/{id}.status is already 'suspended' - see portal_domains.js.
 *     Runs on every sweep pass while the cycle stays overdue+unpaid, relying
 *     entirely on that no-op guard rather than tracking its own "already
 *     suspended for this cycle" bit.
 *
 *   paid / cancelled / expired -> always skipped
 *     No reads beyond the initial query's `in` filter are needed and no
 *     writes/emails ever happen for these - the Firestore query itself
 *     excludes them (see TERMINAL... below), so this is enforced structurally,
 *     not just by an early-return.
 *
 * REMINDERS (independent of the state transitions above - can fire in the
 * same pass as a transition, or on their own):
 *   Fires for any cycle in ['invoiced','paymentPending','gracePeriod','overdue']
 *   at 3 tiers, each deterministic eventId firing exactly once ever:
 *     - 3 days before paymentDueAt:  cycle_reminder_${cycleId}_due_minus_3
 *     - on/after paymentDueAt:       cycle_reminder_${cycleId}_due_today
 *     - 2 days before graceEndsAt:   cycle_reminder_${cycleId}_grace_minus_2
 *   "Nearest tier" mirrors subscription_lifecycle.js's EXPIRING_TIERS_DAYS
 *   pattern, adapted from "days until expiry" to "days relative to
 *   paymentDueAt/graceEndsAt": each tier is independently keyed (not a
 *   single nearest-match slot), because these three tiers are about
 *   different anchor dates (due date vs grace end), unlike
 *   subscription_lifecycle.js's single expiry anchor - firing is still
 *   exactly-once per tier since the eventId is deterministic and
 *   enqueueTemplatedEmail's queue doc id IS the eventId (a second enqueue
 *   with the same id is a safe merge no-op, never a duplicate send).
 * ============================================================================
 */
const { onSchedule } = require('firebase-functions/v2/scheduler');
const admin = require('firebase-admin');
const { RESEND_API_KEY } = require('./email/email_service');
const { enqueueTemplatedEmail } = require('./email/transactional_queue');
const { suspendSchoolCore } = require('./portal_domains');

if (!admin.apps.length) admin.initializeApp();
const db = admin.firestore();

// Duplicated from functions/academic_calendar_billing.js's
// DEFAULT_INVOICE_LEAD_DAYS/DEFAULT_GRACE_PERIOD_DAYS on purpose - functions/
// and public_functions/ are separate Cloud Functions codebases and do not
// cross-import (see that file's header comment for the same pattern).
const DEFAULT_INVOICE_LEAD_DAYS = 14;
const DEFAULT_GRACE_PERIOD_DAYS = 7;

const DAY_MS = 24 * 60 * 60 * 1000;

// Cycle statuses this sweep ever reads/acts on. paid/cancelled/expired are
// deliberately excluded from the query itself, not just skipped in code -
// see the "always skipped" section of the state-machine comment above.
const ACTIVE_CYCLE_STATUSES = ['upcoming', 'invoiced', 'paymentPending', 'gracePeriod', 'overdue'];

// 'suspended' is a member of the Phase 1 cycleStatus enum but this sweep
// never writes it to a cycle doc - see the state-machine comment's judgment
// call above. Included here only so a reader checking "is 'suspended'
// handled anywhere" finds this explanation, not a silent gap.
const _UNUSED_CYCLE_STATUS_SUSPENDED_BY_DESIGN = 'suspended';

function toMillis(value) {
  if (!value) return 0;
  if (typeof value.toMillis === 'function') return value.toMillis();
  if (typeof value === 'number') return value;
  if (value instanceof Date) return value.getTime();
  return 0;
}

function dateLabel(ms) {
  return ms > 0 ? new Date(ms).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' }) : '';
}

function text(value, max = 200) {
  return String(value ?? '').trim().slice(0, max);
}

/** Pure decision function - given a cycle's current fields and "now" (ms),
 * returns the action(s) this sweep should take. No Firestore/admin SDK
 * access, so it is unit-testable in isolation (see
 * subscription_cycle_billing.test.js). Mirrors how
 * functions/academic_calendar_billing.js exports `_validateTerms` as a pure
 * function for the same reason. */
function decideCycleAction(cycle, nowMs, config = {}) {
  const invoiceLeadDays = Number.isFinite(config.invoiceLeadDays) ? config.invoiceLeadDays : DEFAULT_INVOICE_LEAD_DAYS;
  const status = cycle.cycleStatus;
  const termStartMs = toMillis(cycle.termStart);
  const paymentDueMs = toMillis(cycle.paymentDueAt);
  const graceEndsMs = toMillis(cycle.graceEndsAt);

  const result = { transition: null, reminders: [], suspend: false };

  if (status === 'paid' || status === 'cancelled' || status === 'expired') {
    return result; // Always skipped - no writes, no emails.
  }

  // upcoming -> invoiced
  if (status === 'upcoming') {
    const invoiceAtMs = termStartMs - invoiceLeadDays * DAY_MS;
    if (nowMs >= invoiceAtMs) {
      result.transition = 'invoiced';
    }
    // upcoming cycles never get reminders (nothing has been invoiced yet).
    return result;
  }

  // From here, status is one of invoiced|paymentPending|gracePeriod|overdue.
  // paymentPending is treated as a synonym of invoiced for every purpose
  // below - see the state-machine comment's judgment call.
  const isInvoicedLike = status === 'invoiced' || status === 'paymentPending';

  // Reminder tiers - independent of the transition decided below, fire for
  // any non-terminal, already-invoiced cycle.
  if (paymentDueMs > 0) {
    if (nowMs >= paymentDueMs - 3 * DAY_MS && nowMs < paymentDueMs) {
      result.reminders.push('due_minus_3');
    }
    if (nowMs >= paymentDueMs) {
      result.reminders.push('due_today');
    }
  }
  if (graceEndsMs > 0 && nowMs >= graceEndsMs - 2 * DAY_MS && nowMs < graceEndsMs) {
    result.reminders.push('grace_minus_2');
  }

  // invoiced/paymentPending -> gracePeriod
  if (isInvoicedLike && paymentDueMs > 0 && graceEndsMs > 0 && nowMs > paymentDueMs && nowMs <= graceEndsMs) {
    result.transition = 'gracePeriod';
    return result;
  }

  // gracePeriod -> overdue
  if (status === 'gracePeriod' && graceEndsMs > 0 && nowMs > graceEndsMs) {
    result.transition = 'overdue';
    result.suspend = true;
    return result;
  }

  // overdue -> stays overdue, keeps triggering suspension (idempotent no-op
  // once the school is already suspended).
  if (status === 'overdue') {
    result.suspend = true;
  }

  return result;
}

exports.checkSubscriptionCycleBilling = onSchedule(
  { region: 'europe-west1', schedule: 'every 1 hours', timeZone: 'Africa/Kampala', secrets: [RESEND_API_KEY] },
  async () => {
    const nowMs = Date.now();
    const [configSnap, cyclesSnap] = await Promise.all([
      db.collection('platform_billing_config').doc('renewal').get(),
      db.collection('subscription_cycles').where('cycleStatus', 'in', ACTIVE_CYCLE_STATUSES).get(),
    ]);
    const config = configSnap.exists ? configSnap.data() : {};
    const invoiceLeadDays = Number.isFinite(config.invoiceLeadDays) ? config.invoiceLeadDays : DEFAULT_INVOICE_LEAD_DAYS;

    for (const doc of cyclesSnap.docs) {
      const cycle = doc.data() || {};
      const cycleId = doc.id;
      const schoolId = text(cycle.schoolId, 180);
      if (!schoolId) continue;

      try {
        const action = decideCycleAction(cycle, nowMs, { invoiceLeadDays });
        if (!action.transition && action.reminders.length === 0 && !action.suspend) continue;

        const schoolSnap = await db.collection('schools').doc(schoolId).get();
        const school = schoolSnap.exists ? schoolSnap.data() : {};
        const schoolName = text(school.name, 160) || 'Your school';
        const termName = text(cycle.termNumber != null ? `Term ${cycle.termNumber}` : '', 40) || 'this term';
        // Phase 3A: plan-based pricing (cycle.planSnapshot) was replaced by
        // student-count-band pricing (cycle.pricingSnapshot) in
        // functions/academic_calendar_billing.js / functions/student_pricing_bands.js.
        // Old cycles generated before this phase may still carry
        // planSnapshot only; fall back to it so historical reminders still
        // render an amount instead of "UGX 0".
        const pricingSnapshot = cycle.pricingSnapshot || cycle.planSnapshot || {};
        const amountLabel = `${text(pricingSnapshot.currency, 10) || 'UGX'} ${Number(
          pricingSnapshot.amountUgx ?? pricingSnapshot.price ?? 0
        ).toLocaleString('en-UG')}`;
        const dueLabel = dateLabel(toMillis(cycle.paymentDueAt));
        const graceLabel = dateLabel(toMillis(cycle.graceEndsAt));

        let recipient = '';
        const adminSnap = await db.collection('users')
          .where('schoolId', '==', schoolId)
          .where('role', '==', 'schoolAdmin')
          .limit(1)
          .get();
        if (!adminSnap.empty) recipient = text(adminSnap.docs[0].data()?.email, 200);

        // a. Issue invoice: upcoming -> invoiced.
        if (action.transition === 'invoiced') {
          await doc.ref.set({
            cycleStatus: 'invoiced',
            invoiceIssuedAt: admin.firestore.FieldValue.serverTimestamp(),
            paymentStatus: 'unpaid',
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          }, { merge: true });
          await enqueueTemplatedEmail({
            eventId: `cycle_invoice_issued_${cycleId}`,
            templateId: 'cycle_invoice_issued',
            to: recipient,
            data: { schoolName, termName, amountLabel, dueLabel },
          });
        }

        // invoiced/paymentPending -> gracePeriod.
        if (action.transition === 'gracePeriod') {
          await doc.ref.set({
            cycleStatus: 'gracePeriod',
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          }, { merge: true });
        }

        // gracePeriod -> overdue.
        if (action.transition === 'overdue') {
          await doc.ref.set({
            cycleStatus: 'overdue',
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          }, { merge: true });
        }

        // b. Reminders - each tier fires exactly once ever via deterministic
        // eventId, independent of whether a transition also happened above.
        for (const tier of action.reminders) {
          await enqueueTemplatedEmail({
            eventId: `cycle_reminder_${cycleId}_${tier}`,
            templateId: tier === 'grace_minus_2' ? 'cycle_grace_expiring' : 'cycle_reminder',
            to: recipient,
            data: { schoolName, termName, amountLabel, dueLabel, graceLabel, tier },
          });
        }

        // d. Grace expiry -> suspension side-effect (cycleStatus stays
        // 'overdue' - see state-machine comment). suspendSchoolCore itself
        // is the idempotency guard against re-suspending/re-audit-logging.
        if (action.suspend) {
          await suspendSchoolCore(
            db,
            schoolId,
            `Unpaid subscription cycle past grace period (cycle ${cycleId}).`,
            'system:subscription_cycle_billing',
            'AUTO_SUSPEND_UNPAID_CYCLE',
          );
        }
      } catch (error) {
        console.error('subscription_cycle_billing sweep failed for cycle', cycleId, error);
      }
    }
  },
);

exports._decideCycleAction = decideCycleAction;
exports.DEFAULT_INVOICE_LEAD_DAYS = DEFAULT_INVOICE_LEAD_DAYS;
exports.DEFAULT_GRACE_PERIOD_DAYS = DEFAULT_GRACE_PERIOD_DAYS;
